// Configuración de generación por lotes
const TEMAS_POR_BLOG = 1500;
const TEMAS_POR_LOTE = 50; // DeepSeek genera 50 temas por llamada API
const LOTES_POR_BLOG = Math.ceil(TEMAS_POR_BLOG / TEMAS_POR_LOTE); // = 30 lotes

const SHEETS_ID = '14NYqDn77J9nsTjD8ZsvxzDe1lggNwmC6kUZcE3LNbJI';

return BLOGS.map((blog, idx) => ({
  json: { blog, TEMAS_POR_LOTE, LOTES_POR_BLOG, TEMAS_POR_BLOG, SHEETS_ID, blogIndex: idx }
}));

// Generar los números de lote para este blog
const { blog, TEMAS_POR_LOTE, LOTES_POR_BLOG } = $input.item.json;

const lotes = [];
for (let i = 0; i < LOTES_POR_BLOG; i++) {
  const offset = i * TEMAS_POR_LOTE;
  const cantidad = (offset + TEMAS_POR_LOTE <= 1500) ? TEMAS_POR_LOTE : 1500 - offset;
  lotes.push({ json: { ...$input.item.json, lote: i + 1, offset, cantidad } });
}
return lotes;

const response = $input.item.json;
const config = $('Dividir en Lotes de 50').item.json;
const { blog, lote, offset, SHEETS_ID } = config;

// Parsear respuesta de DeepSeek
let rawContent = response.choices?.[0]?.message?.content || '{"temas":[]}';
rawContent = rawContent.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();

let data;
try { data = JSON.parse(rawContent); } catch(e) {
  const match = rawContent.match(/\{.*\}/s);
  data = match ? JSON.parse(match[0]) : { temas: [] };
}

const temas = data.temas || [];

// Calcular fechas de publicación escalonadas
// 1500 artículos en 60 días = 1 cada ~57.6 minutos
const INTERVALO_MS = (60 * 24 * 60 * 60 * 1000) / 1500;
const fechaInicio = new Date();
fechaInicio.setDate(fechaInicio.getDate() + 1); // Empezar mañana
fechaInicio.setHours(8, 0, 0, 0); // Empezar a las 8am

return temas.map((tema, idx) => {
  const numArticulo = offset + idx;
  const fechaPub = new Date(fechaInicio.getTime() + (numArticulo * INTERVALO_MS));
  return {
    json: {
      blogTab: blog.tab,
      blogId: blog.id,
      blogNombre: blog.nombre,
      blogNicho: blog.nicho,
      titulo: tema.titulo || '',
      keyword: tema.keyword || '',
      intencion: tema.intencion || 'informacional',
      formato: tema.formato || 'guia',
      producto_relacionado: tema.producto_relacionado || (blog.productos[0] || ''),
      estado: 'pendiente',
      fecha_publicacion: fechaPub.toISOString(),
      lote,
      num_articulo: numArticulo + 1,
      SHEETS_ID
    }
  };
});
